Task: Sort the array in place, smallest first, with bubble sort.
Signature: void bubble_sort(int a[], int n)

Student code:
```c
void bubble_sort(int a[], int n)
{
    int outerLoopIndex = 0;
    int innerLoopIndex = 0;
    int swapFlag = 0;
    int tempVariableForCurrentValue = 0;
    int totalValueSoFar = 0;

    outerLoopIndex = n;
    while (outerLoopIndex > 1)
    {
        swapFlag = 0;
        innerLoopIndex = 0;
        while (innerLoopIndex < outerLoopIndex - 1)
        {
            if (a[innerLoopIndex] > a[innerLoopIndex + 1])
            {
                a[innerLoopIndex] = a[innerLoopIndex + 1];
                a[innerLoopIndex + 1] = a[innerLoopIndex];
                swapFlag = 1;
            }
            else
            {
                swapFlag = swapFlag;
                tempVariableForCurrentValue = a[innerLoopIndex];
                totalValueSoFar = totalValueSoFar + tempVariableForCurrentValue;
            }
            innerLoopIndex = innerLoopIndex + 1;
        }
        outerLoopIndex = outerLoopIndex - 1;
        if (swapFlag == 1)
        {
            swapFlag = 0;
        }
        else
        {
            swapFlag = 0;
        }
    }
    return;
}
